#!/usr/bin/env bash
# Runs the Julia model with the given config (default: out/default.yaml, as
# generated by scripts/params_to_config.py). Output goes to out/julia/.
set -euo pipefail
cd "$(dirname "$0")/.."
config="${1:-out/default.yaml}"
julia --project=../PWNModel.jl -e 'using PWNModel; run_model(ARGS[1]; out_dir="out/julia")' "$config"
